solution.solution.py:
def initials(name):
    words = name.split()
    if not words:
        return ""
    return words[0][0].upper() + "." + words[-1][0].upper() + "."


def is_palindrome(text):
    letters = text.lower().replace(" ", "")
    return letters == letters[::-1]


def count_vowels(text):
    lower = text.lower()
    return lower.count("a") + lower.count("e") + lower.count("i") + lower.count("o") + lower.count("u")

